def transform(grid):
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            for c in (center - r, center + r):
                if 0 <= c < n:
                    out[r][c] = 2
        for c in range(n):
            if (c - r - center) % 4 == 0 and (r > center or center-r <= c <= center+r):
                if out[r][c] == 0:
                    out[r][c] = 1
    return out
